{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.rts_tat as WITH base_raw AS ( SELECT CASE WHEN UPPER(TRIM(sku)) LIKE \'MP%\' AND UPPER(TRIM(sku)) NOT LIKE \'MP-%\' THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku)), 3) WHEN REGEXP_LIKE(UPPER(TRIM(sku)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku)) END AS sku_group, TRY_TO_DATE(date_of_entry, \'DD/MM/YYYY\') AS inspection_date, online_qty, UPPER(TRIM(warehouse)) AS warehouse, REGEXP_REPLACE( REPLACE( REPLACE( REPLACE( REPLACE(UPPER(TRIM(\"Logic PO\")), \'/\', \',\'), \'&\', \',\'), \'.\', \'-\'), \' \', \'\'), \'\\s+\', \'\') AS logic_po_clean, COALESCE( TRY_TO_DATE(TRIM(delivey_date), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(delivey_date), \'DD/MM/YY\'), TRY_TO_DATE(TRIM(delivey_date), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(delivey_date), \'DD-MM-YY\'), TRY_TO_DATE(TRIM(delivey_date), \'DD-MON-YYYY\'), TRY_TO_DATE(TRIM(delivey_date), \'DD-MON-YY\'), TRY_TO_DATE(TRIM(delivey_date), \'DD MON YYYY\'), TRY_TO_DATE(TRIM(delivey_date), \'DD MON YY\'), TRY_TO_DATE(TRIM(delivey_date), \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(delivey_date)) ) AS planned_date FROM snitch_db.maplemonk.online_goods_main WHERE TRY_TO_DATE(date_of_entry, \'DD/MM/YYYY\') >= \'2026-01-01\' AND UPPER(TRIM(sku)) IS NOT NULL ), vendor_map AS ( SELECT CASE WHEN UPPER(TRIM(sku)) LIKE \'SN%\' OR UPPER(TRIM(sku)) LIKE \'BP%\' THEN UPPER(TRIM(sku)) WHEN UPPER(TRIM(sku)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, ANY_VALUE(from_party) AS vendor_name FROM snitch_db.maplemonk.logic_purchase_order WHERE to_party IS NOT NULL GROUP BY 1 ), logic_po as ( select lot_number, min(order_date) as po_date from snitch_db.maplemonk.logic_purchase_order group by 1 ), po_split AS ( SELECT *, CASE WHEN REGEXP_LIKE(logic_po_clean, \'^(POF|POJ|POB|PBJ)[0-9]{2}SW[0-9]+-NW[0-9]+$\') THEN REGEXP_SUBSTR(logic_po_clean, \'^(POF|POJ|POB|PBJ)[0-9]{2}\') || \'-\' || REGEXP_SUBSTR(logic_po_clean, \'SW([0-9]+)\', 1, 1, \'e\', 1) WHEN SPLIT_PART(logic_po_clean, \',\', 2) <> \'\' THEN SPLIT_PART(logic_po_clean, \',\', 1) WHEN UPPER(warehouse) = \'YELAHANKA-2\' THEN logic_po_clean END AS south_po, CASE WHEN REGEXP_LIKE(logic_po_clean, \'^(POF|POJ|POB|PBJ)[0-9]{2}SW[0-9]+-NW[0-9]+$\') THEN REGEXP_SUBSTR(logic_po_clean, \'^(POF|POJ|POB|PBJ)[0-9]{2}\') || \'-\' || REGEXP_SUBSTR(logic_po_clean, \'NW([0-9]+)\', 1, 1, \'e\', 1) WHEN SPLIT_PART(logic_po_clean, \',\', 2) <> \'\' THEN SPLIT_PART(SPLIT_PART(logic_po_clean, \',\', 1), \'-\', 1) || \'-\' || SPLIT_PART(logic_po_clean, \',\', 2) WHEN warehouse ILIKE \'%NORTH%\' THEN logic_po_clean END AS north_po, CASE WHEN REGEXP_LIKE(logic_po_clean, \'^(POF|POJ|POB|PBJ)[0-9]{2}SW[0-9]+-NW[0-9]+$\') THEN planned_date WHEN SPLIT_PART(logic_po_clean, \',\', 2) <> \'\' THEN planned_date WHEN UPPER(warehouse) = \'YELAHANKA-2\' THEN planned_date END AS south_planned_date, CASE WHEN REGEXP_LIKE(logic_po_clean, \'^(POF|POJ|POB|PBJ)[0-9]{2}SW[0-9]+-NW[0-9]+$\') THEN planned_date WHEN SPLIT_PART(logic_po_clean, \',\', 2) <> \'\' THEN planned_date WHEN warehouse ILIKE \'%NORTH%\' THEN planned_date END AS north_planned_date FROM base_raw ), north_inward AS ( SELECT CASE WHEN UPPER(TRIM(sku_no)) LIKE \'MP%\' AND UPPER(TRIM(sku_no)) NOT LIKE \'MP-%\' THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku_no)), 3) WHEN REGEXP_LIKE(UPPER(TRIM(sku_no)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku_no)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku_no)) END AS sku_group, COALESCE( TRY_TO_DATE(PLANNED_DATE, \'DD-MON-YYYY\'), TRY_TO_DATE(PLANNED_DATE, \'DD-MON-YY\'), TRY_TO_DATE(PLANNED_DATE, \'DD/MM/YYYY\'), TRY_TO_DATE(PLANNED_DATE, \'DD/MM/YY\'), TRY_TO_DATE(PLANNED_DATE, \'DD-MM-YYYY\'), TRY_TO_DATE(PLANNED_DATE, \'DD-MM-YY\'), TRY_TO_DATE(PLANNED_DATE, \'YYYY-MM-DD\') ) AS planned_date, COALESCE( TRY_TO_DATE(actual_delivered_date,\'DD/MM/YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD-MM-YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD-MON-YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD MON YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD-MON-YY\'), TRY_TO_DATE(actual_delivered_date) ) AS north_actual_delivered_date, COALESCE( TRY_TO_DATE(TRIM(considered_delivered_date),\'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD/MM/YY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD-MM-YY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD-MON-YY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD MON YY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD-MON-YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD MON YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date)) ) AS north_considered_delivered_date, delivery_status_type FROM snitch_db.maplemonk.tauru_inward_details_sku_level ), south_inward AS ( SELECT CASE WHEN UPPER(TRIM(sku_no)) LIKE \'MP%\' AND UPPER(TRIM(sku_no)) NOT LIKE \'MP-%\' THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku_no)), 3) WHEN REGEXP_LIKE(UPPER(TRIM(sku_no)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku_no)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku_no)) END AS sku_group, COALESCE( TRY_TO_DATE(PLANNED_DATE, \'DD-MON-YYYY\'), TRY_TO_DATE(PLANNED_DATE, \'DD-MON-YY\'), TRY_TO_DATE(PLANNED_DATE, \'DD/MM/YYYY\'), TRY_TO_DATE(PLANNED_DATE, \'DD/MM/YY\'), TRY_TO_DATE(PLANNED_DATE, \'DD-MM-YYYY\'), TRY_TO_DATE(PLANNED_DATE, \'DD-MM-YY\'), TRY_TO_DATE(PLANNED_DATE, \'YYYY-MM-DD\'), TRY_TO_DATE(PLANNED_DATE, \'DD MON YYYY\') ) AS planned_date, COALESCE( TRY_TO_DATE(UPPER(TRIM(actual_delivered_date)), \'DD MON YYYY\'), TRY_TO_DATE(UPPER(TRIM(actual_delivered_date)), \'DD-MON-YYYY\'), TRY_TO_DATE(UPPER(TRIM(actual_delivered_date)), \'DD MON YY\'), TRY_TO_DATE(UPPER(TRIM(actual_delivered_date)), \'DD-MON-YY\'), TRY_TO_DATE(TRIM(actual_delivered_date), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(actual_delivered_date), \'DD/MM/YY\'), TRY_TO_DATE(TRIM(actual_delivered_date), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(actual_delivered_date), \'DD-MM-YY\'), TRY_TO_DATE(TRIM(actual_delivered_date), \'YYYY-MM-DD\'), CASE WHEN REGEXP_LIKE(TRIM(actual_delivered_date), \'^[0-9]{1,2} [A-Za-z]{3} [0-9]{4}$\') THEN DATE_FROM_PARTS( TO_NUMBER(RIGHT(TRIM(actual_delivered_date), 4)), MONTH(TRY_TO_DATE(UPPER(SPLIT_PART(TRIM(actual_delivered_date), \' \', 2)), \'MON\')), TO_NUMBER(SPLIT_PART(TRIM(actual_delivered_date), \' \', 1)) ) END, CASE WHEN REGEXP_LIKE(TRIM(actual_delivered_date), \'^[0-9]{1,2}-[A-Za-z]{3}-[0-9]{2}$\') THEN DATE_FROM_PARTS( 2000 + TO_NUMBER(RIGHT(TRIM(actual_delivered_date), 2)), MONTH(TRY_TO_DATE(UPPER(SPLIT_PART(TRIM(actual_delivered_date), \'-\', 2)), \'MON\')), TO_NUMBER(SPLIT_PART(TRIM(actual_delivered_date), \'-\', 1)) ) END, TRY_TO_DATE(TRIM(actual_delivered_date)) ) AS south_actual_delivered_date, COALESCE( TRY_TO_DATE(TRIM(considered_delivered_date),\'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD/MM/YY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD-MM-YY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD-MON-YY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD MON YY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD-MON-YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD MON YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date)) ) AS south_considered_delivered_date, delivery_status_type FROM snitch_db.maplemonk.SOUTH_INWARD_DETAILS_SKU_LEVEL ), meta_mapping AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, ANY_VALUE(l1_category) AS l1_category, ANY_VALUE(category) AS category, ANY_VALUE(meta1) AS meta1, ANY_VALUE(meta2) AS meta2, ANY_VALUE(meta3) AS meta3 FROM snitch_db.maplemonk.meta_mapping_cogs_sku GROUP BY 1 ), PHOTOSHOOT_DATE AS ( SELECT SKU_GROUP, MAX(SAMPLE_RECEIVED_DATE) AS SAMPLE_RECEIVED_DATE, MAX(LIVE_DATE) AS LIVE_DATE, MAX(SHOOT_DATE ) AS SHOOT_DATE FROM SNITCH_DB.MAPLEMONK.sku_group_sample_to_live GROUP BY 1 ), final_base AS ( SELECT b.sku_group, mm.l1_category, mm.category, mm.meta1, mm.meta2, mm.meta3, TRY_TO_NUMBER( REPLACE(TRIM(b.online_qty), \',\', \'\') ) as total_qty, b.warehouse, vm.vendor_name, CASE WHEN b.warehouse ILIKE \'%NORTH%\' THEN b.north_po WHEN UPPER(b.warehouse) = \'YELAHANKA-2\' THEN b.south_po ELSE b.logic_po_clean END AS purchase_order, lp.po_date, PD.SHOOT_DATE, PD.SAMPLE_RECEIVED_DATE, PD.LIVE_DATE, b.inspection_date, b.planned_date, CASE WHEN UPPER(b.warehouse) = \'NORTH\' THEN ni.north_actual_delivered_date WHEN UPPER(b.warehouse) = \'YELAHANKA-2\' THEN si.south_actual_delivered_date END AS actual_delivered_date, CASE WHEN UPPER(b.warehouse) = \'NORTH\' THEN ni.delivery_status_type WHEN UPPER(b.warehouse) = \'YELAHANKA-2\' THEN si.delivery_status_type END AS delivery_status_type, CASE WHEN UPPER(b.warehouse) = \'NORTH\' THEN ni.north_considered_delivered_date WHEN UPPER(b.warehouse) = \'YELAHANKA-2\' THEN si.south_considered_delivered_date END AS considered_delivered_date, FROM po_split b LEFT JOIN meta_mapping mm ON b.sku_group = mm.sku_group LEFT JOIN logic_po lp ON ( CASE WHEN b.warehouse ILIKE \'%NORTH%\' THEN b.north_po WHEN UPPER(b.warehouse) = \'YELAHANKA-2\' THEN b.south_po ELSE b.logic_po_clean END ) = lp.lot_number LEFT JOIN vendor_map vm ON b.sku_group = vm.sku_group LEFT JOIN PHOTOSHOOT_DATE PD ON B.SKU_GROUP = PD.SKU_GROUP LEFT JOIN north_inward ni ON b.sku_group = ni.sku_group AND b.planned_date = ni.planned_date AND b.warehouse = \'NORTH\' LEFT JOIN south_inward si ON b.sku_group = si.sku_group AND b.planned_date = si.planned_date AND UPPER(b.warehouse) = \'YELAHANKA-2\' ), putaway_dates AS ( SELECT sku_group, warehouse, putaway_date AS inward_date FROM ( SELECT fb.sku_group, fb.warehouse, p.putaway_completed_date::DATE AS putaway_date, SUM(p.putaway_completed_quantity) OVER ( PARTITION BY fb.sku_group, fb.warehouse, p.putaway_completed_date::DATE ) AS daily_qty FROM final_base fb JOIN snitch_db.maplemonk.putaway_tracking p ON fb.sku_group = CASE WHEN UPPER(TRIM(p.\"Item Type skuCode\")) LIKE \'SN%\' OR UPPER(TRIM(p.\"Item Type skuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(p.\"Item Type skuCode\")) WHEN UPPER(TRIM(p.\"Item Type skuCode\")) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(p.\"Item Type skuCode\"::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE UPPER(TRIM(COALESCE( REGEXP_SUBSTR(p.\"Item Type skuCode\"::STRING, \'^[^-]+-[^-]+\', 1, 1), p.\"Item Type skuCode\"::STRING ))) END AND ( ( fb.warehouse = \'NORTH\' AND p.\"Warehouse Name\" = \'SAPL-NORTH-TAURU\' ) OR ( UPPER(fb.warehouse) = \'YELAHANKA-2\' AND p.\"Warehouse Name\" = \'SAPL-WH2\' ) ) WHERE p.final_type = \'New Inward\' AND fb.actual_delivered_date IS NOT NULL AND p.putaway_completed_date::DATE >= fb.actual_delivered_date ) QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group, warehouse ORDER BY daily_qty DESC, putaway_date DESC ) = 1 ), grn_issues AS ( SELECT UPPER(TRIM(lot_number)) AS lot_number, CASE WHEN UPPER(TRIM(warehouse_name)) = \'SAPL-NORTH-TAURU\' THEN \'NORTH\' WHEN UPPER(TRIM(warehouse_name)) Ilike \'SAPL-WH2\' THEN \'YELAHANKA-2\' ELSE UPPER(TRIM(warehouse_name)) END AS warehouse, LISTAGG(DISTINCT NULLIF(TRIM(issue), \'\'), \', \') AS issue FROM snitch_db.maplemonk.grn_issues_joined WHERE lot_number IS NOT NULL AND NULLIF(TRIM(issue), \'\') IS NOT NULL GROUP BY 1,2 ), final_output AS ( SELECT fb.*, pd.inward_date, gi.issue FROM final_base fb LEFT JOIN putaway_dates pd ON fb.sku_group = pd.sku_group AND fb.warehouse = pd.warehouse LEFT JOIN grn_issues gi ON UPPER(TRIM(fb.purchase_order)) = gi.lot_number AND fb.warehouse = gi.warehouse ), vendor_enriched AS ( SELECT fo.*, UPPER( TRIM( REGEXP_REPLACE( REGEXP_REPLACE( REGEXP_REPLACE(fo.vendor_name, \'[\\r\\n\\t]+\', \' \'), \'\\s+\', \' \' ), \'\\s*-\\s*[^-]+$\', \'\' ) ) ) AS vendor_clean, CASE WHEN vendor_clean IN ( \'INDIAN CONNECTION\', \'KARMA (GU)\', \'ACME INTERNATIONAL LTD\', \'INTENSE FOCUS ITECH PRIVATE LIMITED\', \'POOJA FASHION\', \'AROMA DE FRANCE\', \'GENTEX GLOBAL\', \'A ONE KNITWEARS\', \'STELLA INDUSSTRIES LIMITED\', \'MAXVALUE CREATIONS PRIVATE LIMITED\', \'DHRUV APPARELS\', \'SAMBHAV CAP CREATION\', \'KESAVAM CLOTHING PRIVATE LIMITED\', \'ADITYA INTERNATIONAL\', \'EVELINE INTERNATIONAL\', \'GOOD GOOD WEARS\', \'MAITRI KNITWEAR\', \'MANGLAM COLORS PRIVATE LIMITED\', \'MINERVA FASHION PVT LTD\', \'NEW MIGLANI HOSIERY FACTORY\', \'OBERAI KNITWEAR\', \'SHIVAAY KNITWEAR\', \'SHREE KRISHNA ENTERPRISES\', \'GS CLOTHING\', \'ADEES EXPORTS\', \'ELYSIUM FOOTWEAR CONCEPT PVT LTD\', \'LEATHER LUXURY\', \'SP INTERNATIONAL\', \'DESHNOK INNOVATOR\', \'INDIA BRAIDS PVT LTD\', \'KRISHNA BEADS INDUSTRIES\', \'MODELAMA EXPORTS (P) LTD\', \'AMPH FASHION PVT. LTD\', \'SHREEJI GARMENTS MANUFACTURING PVT LTD\', \'ASM INDUSTRIES (INDIA) PVT. LTD.\', \'B D SILK INDUSTRIES PVT. LTD\', \'KARMA (MU)\', \'SUBHASH POLYTEX LIMITED\', \'THIMBLERR COMMERCE AND TECHNOLOGY PVT LTD\', \'EURO SUITS MANUFACTURING CO PRIVATE LIMITED\' ) THEN \'north\' WHEN vendor_clean IN ( \'TEXPORT INDUSTRIES PVT LTD\', \'ANUVARTHH APPARELS PVT.LTD.\', \'BBI\', \'BLUE MONKEY CLOTHING COMPANY\', \'G G GARMENTS\', \'K P GARMENT HOUSE\', \'KHARVA APPARELS\', \'LEANDRO FASHION\', \'LOHITH CREATIONS\', \'MARQUEE INDUSTRIES PVT LTD\', \'MAX KNITS INC\', \'MSQ CLOTHING LLP\', \'NALANDA DESIGNERS\', \'OM SHIVA SHAKTHI ENTERPRISES\', \'SAI TEXTILES\', \'SRI SAI TEJA CREATION\', \'V D DECORS\', \'VASUKI CREATIONS\', \'VIGNESH APPEARLS\', \'VIGNESH CREATIONS\', \'VIJAY RAM CREATIONS\', \'AMITHRAJ APPARELS\', \'KNOSKIN FASHIONS PVT. LTD\', \'VR CREATIONS\', \'ABHAY APPARELS\', \'AXCELLER\', \'DIVINITEE GENESIS APPAREL PVT LTD\', \'G T EXPORTS\', \'GO GO INTERNATIONAL PRIVATE LTD\', \'HEVIN CLOTHING\', \'KHATUSHREE INDIA\', \'KP PRODUCTION HOUSE LLP\', \'M SQUARE\', \'PRESTEIGE APPAREL PVT LTD\', \'S R APPARELS\', \'SAI TEXTILES SHADEZ\', \'TRIO APPARELS INDIA PVT. LTD\', \'V D FASHIONS\', \'NAVKAR AGENCY\', \'PRANAV INTERNATIONAL KNITWEAR\', \'THANDEESHWARA FASHIONS\', \'ORCHID CLOTH COMPANY\', \'HANUMAN TEXTILES\', \'ADDON CLOTHING\', \'CHECK MATE\', \'CHILLCARE APPARELS PRIVATE LIMITED\', \'ETTRO\', \'GROOVY FASHIONS\', \'LAMSOLEE CLOTHING COMPANY\', \'RAUNAK TEXTILES\', \'RENAISSANCE FASHIONS\', \'SAANVI TRADERS\', \'VISHNU TRADING CO.\', \'VISTA GLOBAL COMPANY\', \'CUT AND SEW EXPORTS\', \'VEEYA FASHION\', \'PADMA SHRI KNIT WEAR\', \'VP KNIT FASHIONS\', \'INDIANA PUNTOS CLOTHING\', \'A N ASSOCIATES\', \'ASIAN CLOTHINGS\', \'VANITHA GARMENTS\', \'WEAREVER\', \'CORE INDIA\', \'GO GO INTERNATIONAL PRIVATE LIMITED\', \'MOTIF CLOTHING CO.\', \'V.D.FASHIONS\', \'WALT ENTERPRISES\', \'VINTAGE\', \'THANDEESWARA FASHIONS\', \'SMART CLOTHING\', \'SILVER SPARK APPAREL LIMITED\' ) THEN \'south\' ELSE NULL END AS vendor_region, CASE WHEN vendor_clean IN ( \'INDIAN CONNECTION\', \'KARMA (GU)\', \'ACME INTERNATIONAL LTD\', \'INTENSE FOCUS ITECH PRIVATE LIMITED\', \'POOJA FASHION\', \'AROMA DE FRANCE\', \'GENTEX GLOBAL\', \'A ONE KNITWEARS\', \'STELLA INDUSSTRIES LIMITED\', \'MAXVALUE CREATIONS PRIVATE LIMITED\', \'ADEES EXPORTS\', \'ELYSIUM FOOTWEAR CONCEPT PVT LTD\', \'LEATHER LUXURY\', \'SP INTERNATIONAL\', \'DESHNOK INNOVATOR\', \'INDIA BRAIDS PVT LTD\', \'KRISHNA BEADS INDUSTRIES\', \'MODELAMA EXPORTS (P) LTD\', \'AMPH FASHION PVT. LTD\', \'SHREEJI GARMENTS MANUFACTURING PVT LTD\', \'ASM INDUSTRIES (INDIA) PVT. LTD.\', \'B D SILK INDUSTRIES PVT. LTD\', \'KARMA (MU)\', \'THIMBLERR COMMERCE AND TECHNOLOGY PVT LTD\', \'EURO SUITS MANUFACTURING CO PRIVATE LIMITED\' ) THEN \'delhi\' WHEN vendor_clean IN ( \'SUBHASH POLYTEX LIMITED\', \'ADITYA INTERNATIONAL\', \'ANKUSH KNITTING WORKS PRIVATE LIMITED\', \'EVELINE INTERNATIONAL\', \'GOOD GOOD WEARS\', \'MAITRI KNITWEAR\', \'MANGLAM COLORS PRIVATE LIMITED\', \'MINERVA FASHION PVT LTD\', \'NEW MIGLANI HOSIERY FACTORY\', \'OBERAI KNITWEAR\', \'SHIVAAY KNITWEAR\', \'SHREE KRISHNA ENTERPRISES\', \'GS CLOTHING\', \'DHRUV APPARELS\', \'SAMBHAV CAP CREATION\' ) THEN \'ludhiana\' WHEN vendor_clean IN ( \'KESAVAM CLOTHING PRIVATE LIMITED\' ) THEN \'kolkata\' WHEN vendor_clean IN ( \'PADMA SHRI KNIT WEAR\', \'VP KNIT FASHIONS\', \'INDIANA PUNTOS CLOTHING\', \'ASIAN CLOTHINGS\', \'VANITHA GARMENTS\', \'WEAREVER\', \'S R APPARELS\' ) THEN \'tirrupur\' WHEN vendor_clean IN ( \'ADDON CLOTHING\', \'CHILLCARE APPARELS PRIVATE LIMITED\', \'LAMSOLEE CLOTHING COMPANY\', \'RENAISSANCE FASHIONS\', \'SAANVI TRADERS\', \'VISTA GLOBAL COMPANY\' ) THEN \'mumbai\' WHEN vendor_region = \'south\' THEN \'bangalore\' ELSE NULL END AS vendor_location FROM final_output fo ) SELECT ve.*, TO_CHAR(ve.inward_date, \'MM\') AS inward_month, CASE WHEN planned_date IS NOT NULL AND sample_received_date IS NOT NULL AND sample_received_date <= planned_date THEN \'ON_TIME\' WHEN planned_date IS NULL AND sample_received_date IS NOT NULL THEN \'ON_TIME\' WHEN planned_date IS NULL AND sample_received_date IS NULL THEN \'ON_TIME\' WHEN planned_date IS NOT NULL AND sample_received_date IS NOT NULL AND sample_received_date > planned_date THEN \'DELAYED\' WHEN planned_date IS NOT NULL AND sample_received_date IS NULL THEN \'DELAYED\' ELSE NULL END AS sample_timeline_status, CASE WHEN planned_date IS NULL AND sample_received_date IS NULL THEN \'PUSH_SAMPLE_P0\' WHEN planned_date IS NOT NULL AND sample_received_date IS NULL THEN \'PUSH_SAMPLE_P1\' WHEN planned_date IS NULL AND sample_received_date IS NOT NULL THEN \'READY_TO_PLAN\' WHEN planned_date IS NOT NULL AND sample_received_date IS NOT NULL AND sample_received_date <= planned_date THEN \'ON_TRACK\' WHEN planned_date IS NOT NULL AND sample_received_date IS NOT NULL AND sample_received_date > planned_date THEN \'DELAYED_EXECUTION\' END AS sample_actionable, CASE WHEN inspection_date IS NOT NULL AND planned_date IS NULL THEN \'QC_DONE\' WHEN planned_date IS NOT NULL AND actual_delivered_date IS NULL AND planned_date >= CURRENT_DATE THEN \'ALLOCATED_UPCOMING\' WHEN planned_date IS NOT NULL AND actual_delivered_date IS NULL AND planned_date < CURRENT_DATE THEN \'IN_TRANSIT\' WHEN actual_delivered_date IS NOT NULL AND inward_date IS NULL THEN \'DELIVERED_TO_WH\' WHEN actual_delivered_date IS NOT NULL AND inward_date IS NOT NULL AND inward_date >= DATEADD(day, -1, CURRENT_DATE) THEN \'RECENTLY_INWARDED\' WHEN actual_delivered_date IS NOT NULL AND inward_date IS NOT NULL AND inward_date >= DATE_TRUNC(\'MONTH\', CURRENT_DATE) AND inward_date < DATEADD(MONTH, 1, DATE_TRUNC(\'MONTH\', CURRENT_DATE)) THEN \'INWARDED_THIS_MONTH\' ELSE \'UNMAPPED\' END AS sku_stage_remarks, CASE WHEN inspection_date IS NOT NULL AND planned_date IS NULL THEN 1 WHEN planned_date IS NOT NULL AND actual_delivered_date IS NULL AND planned_date >= CURRENT_DATE THEN 2 WHEN planned_date IS NOT NULL AND actual_delivered_date IS NULL AND planned_date < CURRENT_DATE THEN 3 WHEN actual_delivered_date IS NOT NULL AND inward_date IS NULL THEN 4 WHEN actual_delivered_date IS NOT NULL AND inward_date IS NOT NULL AND inward_date >= DATEADD(day, -2, CURRENT_DATE) THEN 5 WHEN actual_delivered_date IS NOT NULL AND inward_date IS NOT NULL AND EXTRACT(MONTH FROM inward_date) = EXTRACT(MONTH FROM CURRENT_DATE) AND EXTRACT(YEAR FROM inward_date) = EXTRACT(YEAR FROM CURRENT_DATE) THEN 6 ELSE 99 END AS stage_order, CASE ve.vendor_location WHEN \'delhi\' THEN 1 WHEN \'bangalore\' THEN 7 WHEN \'ludhiana\' THEN 2 WHEN \'tirrupur\' THEN 9 WHEN \'mumbai\' THEN 6 WHEN \'kolkata\' THEN 5 ELSE NULL END AS expected_tat_north, CASE ve.vendor_location WHEN \'delhi\' THEN 7 WHEN \'bangalore\' THEN 1 WHEN \'ludhiana\' THEN 8 WHEN \'tirrupur\' THEN 2 WHEN \'mumbai\' THEN 6 WHEN \'kolkata\' THEN 6 ELSE NULL END AS expected_tat_south, DATEDIFF(day, ve.planned_date, ve.actual_delivered_date) AS actual_tat, CASE WHEN ve.warehouse = \'NORTH\' THEN DATEDIFF(day, ve.planned_date, ve.actual_delivered_date) - CASE ve.vendor_location WHEN \'delhi\' THEN 1 WHEN \'bangalore\' THEN 7 WHEN \'ludhiana\' THEN 2 WHEN \'tirrupur\' THEN 9 WHEN \'mumbai\' THEN 6 WHEN \'kolkata\' THEN 5 ELSE NULL END WHEN UPPER(ve.warehouse) = \'YELAHANKA-2\' THEN DATEDIFF(day, ve.planned_date, ve.actual_delivered_date) - CASE ve.vendor_location WHEN \'delhi\' THEN 7 WHEN \'bangalore\' THEN 1 WHEN \'ludhiana\' THEN 8 WHEN \'tirrupur\' THEN 2 WHEN \'mumbai\' THEN 6 WHEN \'kolkata\' THEN 6 ELSE NULL END END AS tat_deviation, CASE WHEN ve.planned_date IS NULL OR ve.actual_delivered_date IS NULL OR ve.vendor_location IS NULL THEN NULL WHEN ve.warehouse = \'NORTH\' AND tat_deviation <= 0 THEN 0.6 WHEN UPPER(ve.warehouse) = \'YELAHANKA-2\' AND tat_deviation <= 0 THEN 0.6 ELSE 0 END AS tat_points, CASE WHEN ve.planned_date IS NULL THEN NULL WHEN COALESCE(TRIM(ve.issue), \'\') = \'\' THEN 0.4 ELSE 0 END AS issue_points, COALESCE(tat_points, 0) + COALESCE(issue_points, 0) AS perfect_order_score, CASE WHEN COALESCE(tat_points, 0) + COALESCE(issue_points, 0) = 1 THEN 1 ELSE 0 END AS perfect_order_flag FROM vendor_enriched ve;",
                    "transaction": true
                }
            ) }}
